"use strict";

// MAIN 시작화면 심볼 윤곽 데이터
const introSymbolShape = {"alpha":"","width":384,"height":394};

// MAIN 시작화면 메탈 입체 형상
// 투명 심볼의 윤곽을 따라 앞면과 뒷면, 둥근 모서리와 옆면을 생성합니다.
function buildIntroMetalGeometry(shape) {
  const { width, height } = shape;
  const alpha = Uint8Array.from(atob(shape.alpha), (character) => character.charCodeAt(0));
  const distance = Float32Array.from(alpha, (value) => value >= 128 ? width : 0);
  const step = 2 / (height - 1);
  const bevelRadius = 3.5 * height / 197;
  const vertices = [];

  // 가장자리까지의 거리를 양방향으로 계산해 매끈한 모서리의 높이를 정합니다.
  function measureEdgeDistance(reverse) {
    for (let row = 0; row < height; row += 1) {
      const y = reverse ? height - row - 1 : row;
      for (let column = 0; column < width; column += 1) {
        const x = reverse ? width - column - 1 : column;
        const index = y * width + x;
        if (!distance[index]) continue;
        const offset = reverse ? 1 : -1;
        if (x + offset >= 0 && x + offset < width) {
          distance[index] = Math.min(distance[index], distance[index + offset] + 1);
        }
        if (y + offset >= 0 && y + offset < height) {
          distance[index] = Math.min(distance[index], distance[index + offset * width] + 1);
          for (const diagonal of [-1, 1]) {
            if (x + diagonal >= 0 && x + diagonal < width) {
              distance[index] = Math.min(distance[index], distance[index + offset * width + diagonal] + Math.SQRT2);
            }
          }
        }
      }
    }
  }

  measureEdgeDistance(false);
  measureEdgeDistance(true);

  // 모서리에서 안쪽으로 갈수록 둥글게 솟는 금속 표면의 높이를 계산합니다.
  function surfaceHeight(index) {
    const t = Math.min(1, distance[index] / bevelRadius);
    return 0.055 + 0.04 * Math.sin(t * Math.PI / 2);
  }

  // 윤곽 데이터의 한 점을 위치와 표면 법선으로 변환합니다.
  function pointAt(x, y) {
    const index = y * width + x;
    const dx = (surfaceHeight(y * width + Math.min(width - 1, x + 1))
      - surfaceHeight(y * width + Math.max(0, x - 1))) / (2 * step);
    const dy = (surfaceHeight(Math.max(0, y - 1) * width + x)
      - surfaceHeight(Math.min(height - 1, y + 1) * width + x)) / (2 * step);
    return { x: (x - (width - 1) / 2) * step, y: 1 - y * step,
      z: surfaceHeight(index), nx: -dx, ny: -dy, alpha: alpha[index] / 255 - 0.5 };
  }

  // 윤곽과 삼각형이 교차하는 위치를 보간해 계단 현상을 줄입니다.
  function edgePoint(a, b) {
    const t = a.alpha / (a.alpha - b.alpha);
    const result = {};
    for (const key of ["x", "y", "z", "nx", "ny"]) result[key] = a[key] + (b[key] - a[key]) * t;
    result.alpha = 0;
    return result;
  }

  // 금속 표면의 위치와 법선을 WebGL 정점 배열에 추가합니다.
  function addVertex(point, back = false) {
    const normalLength = Math.hypot(point.nx, point.ny, 1);
    vertices.push(point.x, point.y, back ? -point.z : point.z,
      point.nx / normalLength, point.ny / normalLength, (back ? -1 : 1) / normalLength);
  }

  // 윤곽 안쪽 삼각형과 두께가 있는 측면을 함께 만듭니다.
  function addClippedTriangle(triangle) {
    const polygon = [];
    const crossings = [];
    triangle.forEach((a, index) => {
      const b = triangle[(index + 1) % 3];
      if (a.alpha >= 0) polygon.push(a);
      if ((a.alpha >= 0) !== (b.alpha >= 0)) {
        const point = edgePoint(a, b);
        polygon.push(point);
        crossings.push(point);
      }
    });
    for (let index = 1; index < polygon.length - 1; index += 1) {
      for (const back of [false, true]) {
        for (const point of [polygon[0], polygon[index], polygon[index + 1]]) addVertex(point, back);
      }
    }
    if (crossings.length !== 2) return;
    const [a, b] = crossings;
    let nx = b.y - a.y;
    let ny = a.x - b.x;
    const inside = triangle.find((point) => point.alpha >= 0);
    if (nx * (inside.x - a.x) + ny * (inside.y - a.y) > 0) { nx = -nx; ny = -ny; }
    const normalLength = Math.hypot(nx, ny);
    if (normalLength < 1e-10) return;
    nx /= normalLength;
    ny /= normalLength;
    for (const [point, sign] of [[a, 1], [a, -1], [b, 1], [b, 1], [a, -1], [b, -1]]) {
      vertices.push(point.x, point.y, point.z * sign, nx, ny, 0);
    }
  }

  for (let y = 0; y < height - 1; y += 1) {
    for (let x = 0; x < width - 1; x += 1) {
      const index = y * width + x;
      if (Math.max(alpha[index], alpha[index + 1], alpha[index + width], alpha[index + width + 1]) < 128) continue;
      const a = pointAt(x, y), b = pointAt(x + 1, y);
      const c = pointAt(x + 1, y + 1), d = pointAt(x, y + 1);
      addClippedTriangle([a, b, c]);
      addClippedTriangle([a, c, d]);
    }
  }
  // 같은 윤곽점의 옆면 법선을 평균내 회전 중 금속 가장자리의 각진 반사를 줄입니다.
  const sideNormals = new Map();
  for (let index = 0; index < vertices.length; index += 6) {
    if (vertices[index + 5] !== 0) continue;
    const key = `${vertices[index].toFixed(6)},${vertices[index + 1].toFixed(6)}`;
    const normal = sideNormals.get(key) || [0, 0];
    normal[0] += vertices[index + 3];
    normal[1] += vertices[index + 4];
    sideNormals.set(key, normal);
  }
  for (let index = 0; index < vertices.length; index += 6) {
    if (vertices[index + 5] !== 0) continue;
    const key = `${vertices[index].toFixed(6)},${vertices[index + 1].toFixed(6)}`;
    const normal = sideNormals.get(key);
    const length = Math.hypot(...normal);
    if (length > 1e-6) {
      vertices[index + 3] = normal[0] / length;
      vertices[index + 4] = normal[1] / length;
    }
  }
  return new Float32Array(vertices);
}

// MAIN 시작화면 WebGL 메탈 렌더링
// 실제 두께와 금속 반사광을 가진 심볼을 한 바퀴 회전시키고 종료 정리 함수를 돌려줍니다.
function createIntroMetalSymbol(intro, timeline) {
  const canvas = document.createElement("canvas");
  const gl = canvas.getContext("webgl", { alpha: true, antialias: true });
  if (!gl) return () => {};
  const resources = [];
  let frameId = null;
  let disposed = false;

  // 컴파일 오류가 생기면 원래 심볼 이미지로 안전하게 되돌립니다.
  function compileShader(type, source) {
    const shader = gl.createShader(type);
    resources.push(["shader", shader]);
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw new Error("Intro shader compile failed");
    return shader;
  }

  // 애니메이션 프레임과 그래픽 메모리를 시작화면 종료 시 해제합니다.
  function disposeMetalSymbol() {
    if (disposed) return;
    disposed = true;
    window.cancelAnimationFrame(frameId);
    canvas.removeEventListener("webglcontextlost", handleContextLost);
    for (const [type, resource] of resources) {
      if (type === "shader") gl.deleteShader(resource);
      if (type === "program") gl.deleteProgram(resource);
      if (type === "buffer") gl.deleteBuffer(resource);
    }
    canvas.remove();
    intro.classList.remove("is-metal-ready");
  }

  // 그래픽 장치를 사용할 수 없게 되면 원래 심볼 이미지로 복원합니다.
  function handleContextLost(event) {
    event.preventDefault();
    disposeMetalSymbol();
  }

  try {
    const vertexShader = compileShader(gl.VERTEX_SHADER, `
      attribute vec3 aPosition;
      attribute vec3 aNormal;
      uniform mat3 uRotation;
      uniform float uAspect;
      varying vec3 vNormal;
      varying vec3 vPosition;
      void main() {
        vec3 p = uRotation * aPosition;
        vPosition = p;
        vNormal = uRotation * aNormal;
        float viewZ = p.z - 4.5;
        gl_Position = vec4(p.x * 4.0 / uAspect, p.y * 4.0, -1.02 * viewZ - 0.202, -viewZ);
      }
    `);
    const fragmentShader = compileShader(gl.FRAGMENT_SHADER, `
      #ifdef GL_FRAGMENT_PRECISION_HIGH
        precision highp float;
      #else
        precision mediump float;
      #endif
      uniform vec3 uMetalColor;
      varying vec3 vNormal;
      varying vec3 vPosition;
      void main() {
        vec3 normal = normalize(vNormal);
        vec3 view = normalize(vec3(0.0, 0.0, 4.5) - vPosition);
        vec3 reflected = reflect(-view, normal);
        float bandA = (reflected.x + reflected.y * 0.32 - 0.4) / 0.16;
        float bandB = (reflected.x - reflected.y * 0.5 + 0.6) / 0.09;
        float stripA = exp(-bandA * bandA);
        float stripB = exp(-bandB * bandB);
        float ceiling = smoothstep(-0.15, 0.75, reflected.y) * 0.65;
        float rim = pow(clamp(1.0 - abs(dot(normal, view)), 0.0, 1.0), 3.0);
        float shine = stripA * 0.9 + stripB * 0.7 + ceiling;
        vec3 color = uMetalColor * (0.18 + shine * 0.6 + rim * 0.22);
        color += vec3(0.86, 0.85, 0.92) * (shine * 0.5 + rim * 0.18);
        gl_FragColor = vec4(color, 1.0);
      }
    `);
    const program = gl.createProgram();
    resources.push(["program", program]);
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error("Intro shader link failed");
    gl.useProgram(program);
    const geometry = buildIntroMetalGeometry(introSymbolShape);
    const buffer = gl.createBuffer();
    resources.push(["buffer", buffer]);
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, geometry, gl.STATIC_DRAW);
    for (const [name, offset] of [["aPosition", 0], ["aNormal", 12]]) {
      const attribute = gl.getAttribLocation(program, name);
      gl.enableVertexAttribArray(attribute);
      gl.vertexAttribPointer(attribute, 3, gl.FLOAT, false, 24, offset);
    }
    const rotationUniform = gl.getUniformLocation(program, "uRotation");
    const aspectUniform = gl.getUniformLocation(program, "uAspect");
    const color = getComputedStyle(document.documentElement).getPropertyValue("--color-purple-light").trim();
    const channels = /^#[\da-f]{6}$/i.test(color) ? color.slice(1).match(/../g).map((part) => parseInt(part, 16) / 255) : [0.89, 0.8, 1];
    gl.uniform3fv(gl.getUniformLocation(program, "uMetalColor"), channels);
    gl.enable(gl.DEPTH_TEST);
    gl.clearColor(0, 0, 0, 0);
    canvas.className = "main-intro-canvas";
    canvas.setAttribute("aria-hidden", "true");
    intro.append(canvas);
    canvas.addEventListener("webglcontextlost", handleContextLost);
    const started = performance.now();

    // 시간에 맞춰 한 바퀴 회전하며 금속 반사광과 기울어진 옆면을 매 프레임 그립니다.
    function drawMetalSymbol(now) {
      if (disposed || intro.hidden) return;
      const elapsed = Number(timeline?.currentTime ?? (now - started));
      const progress = Math.max(0, Math.min(1, (elapsed - 650) / 2750));
      const eased = progress * progress * (3 - 2 * progress);
      const yaw = eased * Math.PI * 2;
      const pitch = Math.sin(eased * Math.PI * 2) * 0.16;
      const cy = Math.cos(yaw), sy = Math.sin(yaw), cx = Math.cos(pitch), sx = Math.sin(pitch);
      const ratio = Math.min(Math.max(window.devicePixelRatio || 1, 2), 3);
      const width = Math.max(1, Math.round(canvas.clientWidth * ratio));
      const height = Math.max(1, Math.round(canvas.clientHeight * ratio));
      if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
      gl.viewport(0, 0, width, height);
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
      gl.uniform1f(aspectUniform, width / height);
      gl.uniformMatrix3fv(rotationUniform, false, new Float32Array([cy, sx * sy, -cx * sy, 0, cx, sx, sy, -sx * cy, cx * cy]));
      gl.drawArrays(gl.TRIANGLES, 0, geometry.length / 6);
      intro.classList.add("is-metal-ready");
      frameId = window.requestAnimationFrame(drawMetalSymbol);
    }

    drawMetalSymbol(started);
  } catch {
    disposeMetalSymbol();
  }
  return disposeMetalSymbol;
}

// MAIN 시작화면
// 시작화면이 끝나면 스크롤과 키보드 탐색을 복원하고 메인배너 문구를 등장시킵니다.
function initMainIntro() {
  const intro = document.querySelector(".main-intro");
  if (!intro) {
    initHeaderSloganReveal();
    return;
  }
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
  const duration = reducedMotion.matches ? 100 : 5000;
  const animation = intro.getAnimations?.().find((item) => item.animationName === "main-intro-exit");
  const remaining = Math.max(0, duration - Number(animation?.currentTime || 0));
  const content = [...document.querySelectorAll(".site-header, main, .site-footer")];
  const inertBefore = content.map((element) => element.inert);
  let finished = false;
  let fallbackId;
  let disposeSymbol = () => {};

  // CSS 애니메이션 종료나 예외 종료 시 시작화면을 한 번만 정리합니다.
  function finishMainIntro() {
    if (finished) return;
    finished = true;
    window.clearTimeout(fallbackId);
    disposeSymbol();
    intro.hidden = true;
    document.documentElement.classList.remove("is-intro-active");
    content.forEach((element, index) => { element.inert = inertBefore[index]; });
    intro.removeEventListener("animationend", handleIntroEnd);
    reducedMotion.removeEventListener("change", finishMainIntro);
    initHeaderSloganReveal();
  }

  // 심볼 회전이 아닌 전체 시작화면의 종료 이벤트만 처리합니다.
  function handleIntroEnd(event) {
    if (event.target === intro && event.animationName === "main-intro-exit") finishMainIntro();
  }

  if (remaining === 0) {
    finishMainIntro();
    return;
  }
  document.documentElement.classList.add("is-intro-active");
  content.forEach((element) => { element.inert = true; });
  intro.addEventListener("animationend", handleIntroEnd);
  reducedMotion.addEventListener("change", finishMainIntro);
  fallbackId = window.setTimeout(finishMainIntro, remaining + 100);
  if (!reducedMotion.matches) disposeSymbol = createIntroMetalSymbol(intro, animation);
}

initMainIntro();

// MAIN 메인배너 문구 스크롤 애니메이션
// 화면에 들어오는 헤더 문구를 아래에서 위로 한 번씩 나타나게 준비합니다.
function initHeaderSloganReveal() {
  const slogans = document.querySelectorAll(".header-slogan");
  if (!slogans.length || !("IntersectionObserver" in window)
    || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  // 문구가 화면에 들어오면 애니메이션을 실행하고 관찰을 종료합니다.
  function revealSlogans(entries, observer) {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    });
  }

  const observer = new IntersectionObserver(revealSlogans, {
    threshold: 0.15,
    rootMargin: "0px 0px -24px 0px",
  });

  // 각 문구의 시작 위치를 설정한 뒤 화면 진입 여부를 관찰합니다.
  slogans.forEach((slogan) => {
    slogan.classList.add("is-reveal-ready");
    observer.observe(slogan);
  });
}

// PRODUCT LIPS 슬라이더
// 오른쪽 제품 영역에만 마우스 드래그와 터치 스와이프를 적용합니다.
function initLipsSlider() {
  const container = document.querySelector(".lips-swiper");
  if (!container || typeof window.Swiper !== "function") return;
  const section = container.closest(".lips-section");
  const mobile = window.matchMedia("(max-width: 600px)");
  const tablet = window.matchMedia("(max-width: 1024px)");
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  // 화면 크기에 맞는 카드 수와 카드 사이 여백을 계산합니다.
  function getLipsLayout() {
    return {
      slidesPerView: mobile.matches ? 1 : 2,
      spaceBetween: mobile.matches ? 16 : tablet.matches ? 24 : window.innerWidth * 51 / 1920,
    };
  }

  // 페이지 선택 버튼에 키보드로 접근할 수 있는 이름을 지정합니다.
  function renderLipsBullet(index, className) {
    return `<button type="button" class="${className}" aria-label="${index + 1}번째 제품 보기"></button>`;
  }

  const slider = new window.Swiper(container, {
    ...getLipsLayout(),
    loop: true,
    speed: reducedMotion.matches ? 0 : 550,
    grabCursor: true,
    simulateTouch: true,
    threshold: 8,
    watchOverflow: true,
    keyboard: { enabled: true, onlyInViewport: true },
    navigation: {
      prevEl: section.querySelector(".lips-prev"),
      nextEl: section.querySelector(".lips-next"),
    },
    pagination: {
      el: section.querySelector(".lips-pagination"),
      clickable: true,
      renderBullet: renderLipsBullet,
    },
    a11y: {
      prevSlideMessage: "이전 제품",
      nextSlideMessage: "다음 제품",
      slideLabelMessage: "{{slidesLength}}개 중 {{index}}번째 제품",
      paginationBulletMessage: "{{index}}번째 제품 보기",
    },
  });

  // 화면을 바꾸면 카드 수와 여백을 다시 적용합니다.
  function updateLipsLayout() {
    Object.assign(slider.params, getLipsLayout());
    slider.params.speed = reducedMotion.matches ? 0 : 550;
    slider.update();
  }

  window.addEventListener("resize", updateLipsLayout);
  reducedMotion.addEventListener("change", updateLipsLayout);
}

initLipsSlider();

// PRODUCT LIPS 제목 스크롤 애니메이션
// PRODUCT와 LIPS 제목이 화면에 들어오면 아래에서 위로 나타나게 준비합니다.
function initLipsTitleReveal() {
  const titles = document.querySelectorAll(".lips-intro h2, .lips-heading");
  if (!titles.length || !("IntersectionObserver" in window)
    || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  // 화면에 들어온 제목의 애니메이션을 한 번 실행합니다.
  function revealLipsTitles(entries, observer) {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    });
  }

  const observer = new IntersectionObserver(revealLipsTitles, {
    threshold: 0.15,
    rootMargin: "0px 0px -24px 0px",
  });

  // 제목마다 애니메이션 시작 상태를 지정하고 화면 진입을 관찰합니다.
  titles.forEach((title) => {
    title.classList.add("lips-title-reveal");
    observer.observe(title);
  });
}

initLipsTitleReveal();

// LIPS 제품 영역 스크롤 애니메이션
// LIPS 제품 영역이 화면에 들어오면 CASE와 반대로 왼쪽에서 오른쪽으로 진입시킵니다.
function initLipsProductReveal() {
  const products = document.querySelector(".lips-slider-reveal");
  if (!products || !("IntersectionObserver" in window)
    || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  // 제품 영역이 화면에 들어오면 진입 효과를 한 번 실행합니다.
  function revealLipsProducts(entries, observer) {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    });
  }

  const observer = new IntersectionObserver(revealLipsProducts, {
    threshold: 0.1,
    rootMargin: "0px 0px -24px 0px",
  });
  products.classList.add("is-reveal-ready");
  observer.observe(products);
}

initLipsProductReveal();

// PRODUCT CASE 슬라이더
// 케이스를 01부터 오른쪽에서 왼쪽으로 배치하고 드래그와 터치 이동을 적용합니다.
function initCaseSlider() {
  const container = document.querySelector(".case-swiper");
  if (!container || typeof window.Swiper !== "function") return;
  const section = container.closest(".case-section");
  const mobile = window.matchMedia("(max-width: 600px)");
  const tablet = window.matchMedia("(max-width: 1024px)");
  const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

  // 화면 너비에 맞춰 케이스 표시 개수와 간격을 계산합니다.
  function getCaseLayout() {
    return {
      slidesPerView: mobile.matches ? 1 : 2,
      spaceBetween: mobile.matches ? 16 : tablet.matches ? 24 : window.innerWidth * 50 / 1920,
    };
  }

  // 케이스 슬라이드 위치를 선택하는 페이지 버튼을 만듭니다.
  function renderCaseBullet(index, className) {
    return `<button type="button" class="${className}" aria-label="${index + 1}번째 케이스 보기"></button>`;
  }

  const slider = new window.Swiper(container, {
    ...getCaseLayout(),
    direction: "horizontal",
    initialSlide: 0,
    loop: false,
    rewind: false,
    speed: reducedMotion.matches ? 0 : 550,
    grabCursor: true,
    simulateTouch: true,
    threshold: 8,
    watchOverflow: true,
    keyboard: { enabled: true, onlyInViewport: true },
    navigation: {
      prevEl: section.querySelector(".case-prev"),
      nextEl: section.querySelector(".case-next"),
    },
    pagination: {
      el: section.querySelector(".case-pagination"),
      clickable: true,
      renderBullet: renderCaseBullet,
    },
    a11y: {
      prevSlideMessage: "이전 케이스",
      nextSlideMessage: "다음 케이스",
      slideLabelMessage: "{{slidesLength}}개 중 {{index}}번째 케이스",
      paginationBulletMessage: "{{index}}번째 케이스 보기",
    },
  });

  // 화면 크기와 모션 설정이 바뀌면 케이스 슬라이더를 갱신합니다.
  function updateCaseLayout() {
    Object.assign(slider.params, getCaseLayout());
    slider.params.speed = reducedMotion.matches ? 0 : 550;
    slider.update();
  }

  window.addEventListener("resize", updateCaseLayout);
  reducedMotion.addEventListener("change", updateCaseLayout);
}

initCaseSlider();

// CASE 제품과 제목 스크롤 애니메이션
// CASE 제목은 아래에서 위로, 제품 영역은 오른쪽에서 왼쪽으로 진입하도록 준비합니다.
function initCaseProductReveal() {
  const elements = document.querySelectorAll(".case-slider-reveal, .case-heading");
  if (!elements.length || !("IntersectionObserver" in window)
    || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;

  // 각 요소가 화면에 들어오면 해당 진입 효과를 한 번 실행합니다.
  function revealCaseProducts(entries, observer) {
    entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      entry.target.classList.add("is-visible");
      observer.unobserve(entry.target);
    });
  }

  const observer = new IntersectionObserver(revealCaseProducts, {
    threshold: 0.1,
    rootMargin: "0px 0px -24px 0px",
  });
  // 제목과 제품을 각각 관찰하여 서로 다른 방향의 애니메이션을 실행합니다.
  elements.forEach((element) => {
    element.classList.add("is-reveal-ready");
    observer.observe(element);
  });
}

initCaseProductReveal();

